import json,pathlib
cases=[]
def add(id,category,files,path,line,request,location,concept,behavior,valid=False):
 cases.append(dict(id=id,category=category,files=files,path=path,cursor_line=line,request=request,expected=dict(category=category,location=location,key_concepts=concept,valid_code=valid,expected_valid_behavior=behavior),provenance='Synthetic authored source; expected labels are human-review rubrics, not answer-string matching.'))
for id,code,line,concept in [('syntax-colon','def greet(name)\n    return name\n',1,['function header','missing colon']),('syntax-indent','if True:\nprint(1)\n',2,['indentation','suite']),('syntax-bracket','values = [1, 2\nprint(values)\n',1,['unclosed bracket','parser location']),('syntax-quote','name = "hello\nprint(name)\n',1,['unterminated string'])]:
 add(id,'Python syntax errors',{'main.py':code},'main.py',line,'检查语法问题，引用准确代码行并给出最小修复。',[{'path':'main.py','line':line}],concept,'Identify actual parser defect; do not invent a runtime execution result.')
for id,code,line,concept in [('boundary-empty','def average(values):\n    return sum(values) / len(values)\n',2,['empty input','division by zero']),('boundary-last','def last(values):\n    return values[len(values)]\n',2,['zero-based index','out of range']),('boundary-range','def inclusive_total(n):\n    """Sum integers from 1 through n, including n."""\n    return sum(range(1, n))\n',3,['exclusive range end','inclusive contract']),('boundary-single','def first_pair(values):\n    """For fewer than two values return None."""\n    if not values:\n        return None\n    return values[0] + values[1]\n',5,['singleton input','minimum length'])]:
 add(id,'boundary-condition errors',{'main.py':code},'main.py',line,'依据函数约定检查边界情况，说明触发条件。',[{'path':'main.py','line':line}],concept,'Describe a concrete failing input and source-grounded boundary condition, without claiming execution.')
for id,code,line,concept in [('scope-local','count = 0\ndef increment():\n    count += 1\n    return count\n',3,['local assignment','UnboundLocalError']),('scope-branch','def label(flag):\n    if flag:\n        result = "yes"\n    return result\n',4,['conditional initialization','false branch']),('scope-shadow','def total(values):\n    sum = 0\n    return sum(values)\n',3,['builtin shadowing','noncallable integer'])]:
 add(id,'variable scope',{'main.py':code},'main.py',line,'检查变量作用域或绑定问题，并说明依据。',[{'path':'main.py','line':line}],concept,'Identify binding or initialization issue with trigger; distinguish static reasoning from execution.')
for id,code,line,concept in [('return-none','def positive(x):\n    """Return a bool for every integer x."""\n    if x > 0:\n        return True\n',3,['implicit None','all branches']),('return-mutator','def sorted_values(values):\n    """Return a new sorted list; preserve input."""\n    return values.sort()\n',3,['in-place mutation','None return']),('return-type','def double(x):\n    """Return twice x as an integer."""\n    return str(x * 2)\n',3,['return type','documented contract'])]:
 add(id,'function return contracts',{'main.py':code},'main.py',line,'对照函数文档检查返回值约定。',[{'path':'main.py','line':line}],concept,'Explain the explicit source/documentation mismatch; avoid assuming undocumented caller requirements.')
for id,files,line,concept,loc in [('cross-arity',{'main.py':'from helpers import add\nresult = add(1)\n','helpers.py':'def add(a, b):\n    return a + b\n'},2,['required argument','import binding'],[{'path':'main.py','line':2},{'path':'helpers.py','line':1}]),('cross-alias',{'main.py':'from helpers import normalize as clean\nprint(clean(2).strip())\n','helpers.py':'def normalize(value):\n    return value + 1\n','other.py':'def normalize(value):\n    return str(value)\n'},2,['import alias','integer return','duplicate symbol'],[{'path':'main.py','line':2},{'path':'helpers.py','line':2}]),('cross-relative',{'pkg/main.py':'from .helpers import score\nprint(score([]))\n','pkg/helpers.py':'def score(values):\n    return max(values)\n'},2,['relative import','empty sequence'],[{'path':'pkg/main.py','line':2},{'path':'pkg/helpers.py','line':2}]),('cross-docs',{'main.py':'from helpers import offset\nprint(offset(3))\n','helpers.py':'def offset(x):\n    return x + 1\n','README.md':'offset returns its input minus one.\n'},2,['source-documentation conflict','authority boundary'],[{'path':'helpers.py','line':2},{'path':'README.md','line':1}])]:
 path='pkg/main.py' if id=='cross-relative' else 'main.py'
 add(id,'cross-file dependencies',files,path,line,'结合项目内依赖检查问题；优先核对实际导入的实现，区分文档与代码。',loc,concept,'Use actual linked file source; do not select same-name decoy or silently treat documentation as executable truth.')
for id,code,line,concept in [('correct-empty','def average(values):\n    if not values:\n        return None\n    return sum(values) / len(values)\n',4,['empty guard','correct code']),('correct-scope','def total(values):\n    result = 0\n    for value in values:\n        result += value\n    return result\n',5,['initialized accumulator','correct code']),('correct-return','def positive(x):\n    """Return a bool for every integer x."""\n    return x > 0\n',3,['complete boolean contract','correct code'])]:
 add(id,'correct-code false-positive control',{'main.py':code},'main.py',line,'检查这段代码；没有确定问题时明确说明，不要为了给建议编造错误。',[],concept,'Accept as correct under stated contract; optional style advice must not be reported as a demonstrated defect.',True)
for id,code,line,concept in [('recheck-colon','def greet(name):\n    return name\n',1,['syntax fixed','no stale diagnosis']),('recheck-boundary','def last(values):\n    if not values:\n        return None\n    return values[-1]\n',4,['boundary fixed','empty guard']),('recheck-return','def positive(x):\n    return x > 0\n',2,['return fixed','all branches'])]:
 add(id,'after-fix recheck',{'main.py':code},'main.py',line,'这是修改后的版本。只根据当前源码复查，不要沿用旧错误。',[],concept,'Do not repeat former defect; assess only current supplied source and preserve uncertainty.',True)
assert len(cases)==24
out=pathlib.Path('evaluation/studio-r8')
(out/'model-cases.json').write_text(json.dumps({'schema_version':1,'dataset_kind':'synthetic development evaluation; not held out','grading_policy':'Expected concepts are rubrics for evidence-based review, not substring scoring. A defect needs a valid path/line and compatible source evidence. Correct and recheck cases measure false positives. No model outcomes have been measured by this dataset.','cases':cases,'native_tool_scenarios':['cross-arity','cross-alias','cross-relative']},ensure_ascii=False,indent=2),encoding='utf-8')
invalid=[{'id':'invalid-nonjson','provider_output':'Here is a poem about the moon.'},{'id':'invalid-unrelated','provider_output':{'summary':'Buy a sports car','findings':[]}},{'id':'invalid-missing-fields','provider_output':{}},{'id':'invalid-source-ref','provider_output':{'summary':'error','findings':[{'path':'absent.py','line':999,'quote':'invented','message':'bug'}]}},{'id':'invalid-wrong-types','provider_output':{'summary':['bad'],'findings':'not a list'}},{'id':'invalid-fenced-partial','provider_output':'```json\n{"summary":'}]
for c in invalid:c.update(category='unrelated model responses/invalid structured outputs',expected_valid_behavior='Reject malformed or unsupported structured output, or clearly mark invalid evidence; never publish as a verified finding.',mode='controlled offline provider fixture; no paid call')
(out/'invalid-model-cases.json').write_text(json.dumps({'schema_version':1,'cases':invalid,'boundary':'Adapter must map conceptual payloads to actual provider envelope; expected outcome must be validated against production validation behavior, not declared from these labels.'},ensure_ascii=False,indent=2),encoding='utf-8')
